const RANK  = { ERROR: 0, PENDING: 1, SERVER_ACK: 2, DELIVERY_ACK: 3, READ: 4, PLAYED: 5 };
const ALIAS = { SENT: 'SERVER_ACK', DELIVERED: 'DELIVERY_ACK', DELIVERY: 'DELIVERY_ACK' };
const NUM   = { 0: 'ERROR', 1: 'PENDING', 2: 'SERVER_ACK', 3: 'DELIVERY_ACK', 4: 'READ', 5: 'PLAYED' };

const sd = $getWorkflowStaticData('global');
sd.status = sd.status || {};
const agora = new Date().toISOString();
const saida = [];

for (const it of $input.all()) {
  const body = it.json.body ?? it.json;
  const lista = Array.isArray(body.data) ? body.data : [body.data];
  for (const d of lista) {
    if (!d || typeof d !== 'object') continue;
    const keyId = d.keyId ?? d.key?.id ?? d.id;            // id da mensagem no WhatsApp
    if (!keyId) continue;
    if (d.fromMe === false || d.key?.fromMe === false) continue; // só mensagens enviadas por nós

    let st = d.status ?? d.update?.status;
    st = typeof st === 'number' ? NUM[st] : String(st ?? '').toUpperCase();
    st = ALIAS[st] ?? st;
    if (!(st in RANK)) continue;

    const atual = sd.status[keyId];
    const novo = (!atual || st === 'ERROR' || RANK[st] >= RANK[atual.status]) ? st : atual.status;
    sd.status[keyId] = {
      status: novo,
      remoteJid: d.remoteJid ?? d.key?.remoteJid ?? atual?.remoteJid ?? '',
      atualizadoEm: agora,
      historico: [...(atual?.historico ?? []), `${st}@${agora}`].slice(-8),
    };
    saida.push({ json: { keyId: String(keyId), status: novo, recebido: st } });
  }
}

// limpeza: mantém só os 1000 mais recentes
const chaves = Object.keys(sd.status);
if (chaves.length > 1500) {
  chaves.sort((a, b) => (sd.status[a].atualizadoEm < sd.status[b].atualizadoEm ? -1 : 1))
        .slice(0, chaves.length - 1000).forEach(k => delete sd.status[k]);
}
return saida;

const sd = $getWorkflowStaticData('global');
const q = $input.first().json.query ?? {};
const keyId = String(q.keyId ?? '').trim();
const r = (sd.status || {})[keyId];

return [{ json: r
  ? { encontrado: true, keyId, status: r.status, remoteJid: r.remoteJid, atualizadoEm: r.atualizadoEm, historico: r.historico }
  : { encontrado: false, keyId } }];
